import { PutItemCommand } from 'dynamodb-toolbox/entity/actions/put';
import { ScanCommand } from 'dynamodb-toolbox/table/actions/scan';
import { MODELO_SESION, MODELO_GIMNASIO, TABLA_SESIONES } from '../../models/gimnasio-sesion.model.mjs';

export async function crearSesionRepository(sesion) {
  await MODELO_SESION.build(PutItemCommand)
    .item(sesion)
    .options({ condition: { attr: 'sesionId', exists: false } })
    .send();
}

export async function listarSesionesRepository() {
  const { Items = [] } = await TABLA_SESIONES.build(ScanCommand)
    .entities(MODELO_SESION)
    .options({ consistent: true })
    .send();
  return Items;
}

