import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_SESION, MODELO_GIMNASIO, TABLA_SESIONES } from '../../models/gimnasio-sesion.model.mjs';

export async function buscarGimnasioRepository(gimnasioId) {
  const { Item } = await MODELO_GIMNASIO.build(GetItemCommand)
    .key({ gimnasioId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarGimnasioRepository(gimnasioId, minimo) {
  const { Items = [] } = await TABLA_SESIONES.build(QueryCommand)
